using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

// Build test data
var smallAnalyzer = new TextAnalyzer("The quick brown fox jumps over the lazy dog near the river bank");
var rng = new Random(42);
var words = new string[10_000];
for (int i = 0; i < words.Length; i++)
    words[i] = new string((char)('a' + rng.Next(26)), rng.Next(1, 15));
var largeAnalyzer = new TextAnalyzer(string.Join(' ', words));

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine();

// Warmup + benchmark helper
void Bench(string name, Action action, int iterations = 500_000)
{
    // Warmup
    for (int i = 0; i < 1000; i++) action();

    // Collect multiple samples
    var samples = new double[5];
    for (int s = 0; s < samples.Length; s++)
    {
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++) action();
        sw.Stop();
        samples[s] = sw.Elapsed.TotalNanoseconds / iterations;
    }
    Array.Sort(samples);
    double median = samples[samples.Length / 2];
    double min = samples[0];
    double max = samples[^1];
    Console.WriteLine($"{name,-40} {median,10:F1} ns/op  (min={min:F1}, max={max:F1})");
}

Bench("AverageWordLength_Small", () => smallAnalyzer.AverageWordLength());
Bench("AverageWordLength_Large", () => largeAnalyzer.AverageWordLength(), 50_000);
Bench("WordLengthHistogram_Small", () => smallAnalyzer.WordLengthHistogram());
Bench("WordLengthHistogram_Large", () => largeAnalyzer.WordLengthHistogram(), 10_000);
Bench("UniqueWordCount_Small", () => smallAnalyzer.UniqueWordCount());
Bench("UniqueWordCount_Large", () => largeAnalyzer.UniqueWordCount(), 1_000);

